import re
# Parse detach_ln_v2_s3 eval log
with open('/root/poll_eval_detach_ln_v2_s3.log') as f:
    text = f.read()
# Find per-task TSR/CAR lines
pattern = r'Task (\d+).*?TSR=([\d.]+)\s+CAR=([\d.]+)'
# The per-task results appear with multiline format
lines = text.split('\n')
results = {}
current_task = None
for line in lines:
    m = re.search(r'Task (\d+)', line)
    if m:
        current_task = int(m.group(1))
    # Look for TSR=X.XXX CAR=X.XXX on same line or TSR only
    m2 = re.search(r'TSR=([\d.]+)\s+CAR=([\d.]+)', line)
    if m2 and current_task is not None and current_task not in results:
        results[current_task] = {'TSR': float(m2.group(1)), 'CAR': float(m2.group(2))}
    # Look for standalone CAR line
    m3 = re.search(r\"CAR=([\d.]+)\", line)
    if m3 and current_task is not None and current_task in results and 'CAR' not in results[current_task]:
        results[current_task]['CAR'] = float(m3.group(1))

# Also look for pattern like  TSR=x.xxx  followed by  CAR=x.xxx on next line
for i, line in enumerate(lines):
    m = re.search(r'Task (\d+)', line)
    if m:
        tid = int(m.group(1))
        # Search next few lines for TSR and CAR
        tsr = car = None
        for j in range(i, min(i+10, len(lines))):
            tm = re.search(r'TSR=([\d.]+)', lines[j])
            cm = re.search(r'CAR=([\d.]+)', lines[j])
            if tm:
                tsr = float(tm.group(1))
            if cm:
                car = float(cm.group(1))
        if tsr is not None and car is not None and tid not in results:
            results[tid] = {'TSR': tsr, 'CAR': car}

for tid in sorted(results.keys()):
    print(f'T{tid}: TSR={results[tid][\"TSR\"]}, CAR={results[tid][\"CAR\"]}')

# Overall
m_overall = re.search(r'TSR = ([\d.]+).*?CAR = ([\d.]+)', text)
if m_overall:
    print(f'Overall: TSR={m_overall.group(1)}, CAR={m_overall.group(2)}')
